steps.snippet:
index = device.find(text='OsmAnd')
if index is None:
    index = device.find(description='OsmAnd')
if index is None:
    raise LookupError("OsmAnd app icon not found on screen")
device.click(index=index)

import re
elements = device.elements()
scale = None
for el in elements:
    if el.get('class_name') == 'TextView' and not el.get('clickable') and el.get('text'):
        if re.match(r'^[\d,.]+\s*(mi|km|m)$', el['text']):
            scale = el
            break
if scale is None:
    raise RuntimeError("Map scale bar not found")
device.click(index=scale['index'])

search_idx = device.find(hint='Type to search all', editable=True)
if search_idx is None:
    raise RuntimeError("Search field not found")
elements = device.elements()
search_text = elements[search_idx].get('text', '')
if search_text and search_text != 'Type to search all':
    clear_idx = device.find(description='Clear', clickable=True)
    if clear_idx is None:
        raise RuntimeError("Clear button not found")
    device.click(clear_idx)
